//! # PostScript names module
//!
//! Port of FreeType 2.6.5's `psnames` module
//! (`src/psnames/{psmodule.c,pstables.h}`) and of the PostScript charmap
//! service specification (`include/freetype/internal/services/svpscmap.h`).
//!
//! FreeType configuration options `FT_CONFIG_OPTION_POSTSCRIPT_NAMES` and
//! `FT_CONFIG_OPTION_ADOBE_GLYPH_LIST` are both enabled, matching this
//! port.  The position-independent-code (PIC) support of `pspic.c` has no
//! Rust equivalent: the service records are plain `static` items here.
//!
//! Port notes:
//!
//! - Glyph names are returned as borrowed `&'static str` slices of the
//!   static name table, so the `PS_FreeGlyphNameFunc` hook of the C API is
//!   intentionally not ported.
//! - `PS_UnicodesRec::cmap` (the embedded `FT_CMapRec`) is omitted because
//!   the character map object model is not part of this crate yet; the
//!   record keeps the `num_maps`/`maps` payload that the drivers consume.
//! - `ps_unicodes_init` reports `TtError::OUT_OF_MEMORY` through
//!   `Vec::try_reserve` instead of relying on the allocator.

#![cfg_attr(not(test), no_std)]
extern crate alloc;

use alloc::vec::Vec;
use codevar_logger::log_error;
use codevar_truetype_core::{TtError, TtResult};

/// Identifier of the PostScript charmap service (`FT_SERVICE_ID_POSTSCRIPT_CMAPS`).
pub const FT_SERVICE_ID_POSTSCRIPT_CMAPS: &str = "postscript-cmaps";

/// Bit 31 marks a glyph variant in a Unicode map entry (`VARIANT_BIT`).
///
/// Glyph names with a non-initial dot (`A.swash`, `e.final`) resolve to the
/// base glyph value OR'ed with this bit.
pub const VARIANT_BIT: u32 = 0x8000_0000;

/// Number of Macintosh glyph name indices in `ft_mac_names` (`FT_NUM_MAC_NAMES`).
pub const FT_NUM_MAC_NAMES: usize = 258;

/// Number of Adobe Standard Strings indices in `ft_sid_names` (`FT_NUM_SID_NAMES`).
pub const FT_NUM_SID_NAMES: usize = 391;

/// Number of extra glyph name to Unicode mappings added to built charmaps
/// (`EXTRA_GLYPH_LIST_SIZE`).
pub const EXTRA_GLYPH_LIST_SIZE: usize = 10;

/// Strip the variant bit from a Unicode map value (`BASE_GLYPH`).
///
/// Returns the base Unicode value of a glyph name; for a plain glyph this
/// is the value itself, for a variant such as `A.swash` the Unicode value
/// of `A`.
#[inline]
pub const fn base_glyph(code: u32) -> u32 {
    code & !VARIANT_BIT
}

/// Return the NUL-terminated PostScript glyph name starting at `offset` in
/// [`FT_STANDARD_GLYPH_NAMES`].
///
/// Offsets are the values stored in [`FT_MAC_NAMES`] and [`FT_SID_NAMES`].
/// An out-of range offset (which the C tables never contain) yields an
/// empty string instead of reading outside the table.
#[inline]
fn standard_glyph_name(offset: usize) -> &'static str {
    let table = FT_STANDARD_GLYPH_NAMES;
    let rest = match table.get(offset..) {
        Some(rest) => rest,
        None => return "",
    };
    let end = rest
        .iter()
        .position(|&c| c == 0)
        .unwrap_or(rest.len());
    core::str::from_utf8(&rest[..end]).unwrap_or("")
}

/// Return the glyph name for a Macintosh name index
/// (`ps_get_macintosh_name`).
///
/// Like the C implementation the index is clamped to `0` when it is out of
/// range, so the returned name is always valid (`.notdef` for index `0`).
pub fn ps_get_macintosh_name(name_index: u32) -> &'static str {
    let index = match usize::try_from(name_index) {
        Ok(index) if index < FT_NUM_MAC_NAMES => index,
        _ => 0,
    };
    standard_glyph_name(FT_MAC_NAMES[index] as usize)
}

/// Return an Adobe Standard Strings name (`ps_get_standard_strings`).
///
/// Returns `None` when `sid` is out of range, which matches the C
/// function returning `NULL`.
pub fn ps_get_standard_strings(sid: u32) -> Option<&'static str> {
    let index = usize::try_from(sid).ok()?;
    let offset = *FT_SID_NAMES.get(index)?;
    Some(standard_glyph_name(offset as usize))
}

/// Search the compressed Adobe Glyph List for `name`
/// (`ft_get_adobe_glyph_index`).
///
/// `name` is the byte range the C implementation receives as the
/// `[name, limit)` pointer pair: only bytes inside the slice are read, so
/// callers pass either the whole glyph name or its leading part up to a
/// variant dot.
///
/// Returns the Unicode value stored in the list, or `0` when the name is
/// not present.  Glyph names are assumed to be ASCII, as in FreeType.
pub fn ft_get_adobe_glyph_index(name: &[u8]) -> u32 {
    let table = FT_ADOBE_GLYPH_LIST;
    if name.is_empty() {
        return 0;
    }

    let mut pos = 0_usize; // position inside `name`
    let first = name[pos];
    pos += 1;

    // root node: byte 0 is the (empty) root letter, byte 1 the child count
    let count = i32::from(table[1]);
    let p = 2_usize;
    let mut min = 0_i32;
    let mut max = count;
    let mut node = None;

    while min < max {
        let mid = min + (max - min) / 2;
        let entry = p + (mid as usize) * 2;
        let offset = ((usize::from(table[entry])) << 8) | usize::from(table[entry + 1]);
        let c2 = table[offset] & 127;
        if c2 == first {
            node = Some(offset);
            break;
        }
        if i32::from(c2) < i32::from(first) {
            min = mid + 1;
        } else {
            max = mid;
        }
    }

    let mut p = match node {
        Some(p) => p,
        None => return 0,
    };

    loop {
        // `name >= limit`: the name ended on a node that carries a value
        if pos >= name.len() {
            if (table[p] & 128) == 0 && (table[p + 1] & 128) != 0 {
                return ((u32::from(table[p + 2])) << 8) | u32::from(table[p + 3]);
            }
            return 0;
        }
        let c = name[pos];
        pos += 1;

        // continuation of a multi-letter node
        if table[p] & 128 != 0 {
            p += 1;
            if c != (table[p] & 127) {
                return 0;
            }
            continue;
        }
        // last letter of `p` reached: select among its children
        p += 1;
        let mut count = i32::from(table[p] & 127);
        if table[p] & 128 != 0 {
            p += 2;
        }
        p += 1;

        let mut next = None;
        while count > 0 {
            let offset = ((usize::from(table[p])) << 8) | usize::from(table[p + 1]);
            if c == (table[offset] & 127) {
                next = Some(offset);
                break;
            }
            p += 2;
            count -= 1;
        }

        p = match next {
            Some(next) => next,
            None => return 0,
        };
    }
}

/// Return the Unicode value corresponding to a glyph name
/// (`ps_unicode_value`).
///
/// The port follows the C control flow exactly:
///
/// 1. a `uni` prefix followed by four uppercase hexadecimal digits,
/// 2. a `u` prefix followed by four to six uppercase hexadecimal digits,
/// 3. otherwise a lookup of the leading part of the name (up to a
///    non-initial dot) in the Adobe Glyph List.
///
/// Reads past the end of `glyph_name` behave like the C code reading the
/// terminating NUL byte, so short names are handled without panicking.
pub fn ps_unicode_value(glyph_name: &str) -> u32 {
    let name = glyph_name.as_bytes();
    // Emulates `glyph_name[i]` on a NUL-terminated C string.
    let at = |i: usize| -> u8 { name.get(i).copied().unwrap_or(0) };

    // `uniXXXX`: exactly four hexadecimal digits must follow
    if at(0) == b'u' && at(1) == b'n' && at(2) == b'i' {
        let mut value = 0_u32;
        let mut count = 4;
        let mut p = 3_usize;

        while count > 0 {
            let c = at(p);
            let mut d = u32::from(c).wrapping_sub(u32::from(b'0'));
            if d >= 10 {
                d = u32::from(c).wrapping_sub(u32::from(b'A'));
                d = if d >= 6 { 16 } else { d + 10 };
            }
            // non-uppercase hexadecimal digit (this also rejects bytes
            // below `0` through the unsigned wrap-around)
            if d >= 16 {
                break;
            }
            value = (value << 4) + d;
            count -= 1;
            p += 1;
        }

        if count == 0 {
            if at(p) == 0 {
                return value;
            }
            if at(p) == b'.' {
                return value | VARIANT_BIT;
            }
        }
    }

    // `uXXXX..`: four to six hexadecimal digits
    if at(0) == b'u' {
        let mut value = 0_u32;
        let mut count = 6;
        let mut p = 1_usize;

        while count > 0 {
            let c = at(p);
            let mut d = u32::from(c).wrapping_sub(u32::from(b'0'));
            if d >= 10 {
                d = u32::from(c).wrapping_sub(u32::from(b'A'));
                d = if d >= 6 { 16 } else { d + 10 };
            }
            if d >= 16 {
                break;
            }
            value = (value << 4) + d;
            count -= 1;
            p += 1;
        }

        if count <= 2 {
            if at(p) == 0 {
                return value;
            }
            if at(p) == b'.' {
                return value | VARIANT_BIT;
            }
        }
    }
    // Look for a non-initial dot to detect variants such as `A.swash`,
    // then look up the leading part in the Adobe Glyph List.
    let mut dot = None;
    for (i, &c) in name.iter().enumerate() {
        if c == 0 {
            break;
        }
        if c == b'.' && i > 0 {
            dot = Some(i);
            break;
        }
    }

    match dot {
        None => ft_get_adobe_glyph_index(name),
        Some(index) => ft_get_adobe_glyph_index(&name[..index]) | VARIANT_BIT,
    }
}

/// Unicode values of the extra glyphs that are added to built charmaps
/// (`ft_extra_glyph_unicodes`).
const FT_EXTRA_GLYPH_UNICODES: [u32; EXTRA_GLYPH_LIST_SIZE] = [
    /* WGL 4 */
    0x0394, 0x03A9, 0x2215, 0x00AD, 0x02C9, 0x03BC, 0x2219, 0x00A0, /* Romanian */
    0x021A, 0x021B,
];

/// NUL-separated glyph names of the extra glyphs (`ft_extra_glyph_names`).
static FT_EXTRA_GLYPH_NAMES: &[u8] =
    b"Delta\x00Omega\x00fraction\x00hyphen\x00macron\x00mu\x00periodcentered\x00space\x00Tcommaaccent\x00tcommaaccent\x00";

/// Offsets of the extra glyph names into [`FT_EXTRA_GLYPH_NAMES`]
/// (`ft_extra_glyph_name_offsets`).
const FT_EXTRA_GLYPH_NAME_OFFSETS: [usize; EXTRA_GLYPH_LIST_SIZE] = [0, 6, 12, 21, 28, 35, 38, 53, 59, 72];

/// Compare `gname` with extra glyph name `n` the way `ft_strcmp` does in
/// `ps_check_extra_glyph_name`.
fn extra_glyph_name_eq(n: usize, gname: &str) -> bool {
    let gb = gname.as_bytes();
    // `strcmp` stops at the first NUL of either operand
    let glen = gb
        .iter()
        .position(|&c| c == 0)
        .unwrap_or(gb.len());

    let start = match FT_EXTRA_GLYPH_NAME_OFFSETS.get(n) {
        Some(&start) => start,
        None => return false,
    };
    let table = FT_EXTRA_GLYPH_NAMES;
    let rest = &table[start..];
    let elen = rest
        .iter()
        .position(|&c| c == 0)
        .unwrap_or(rest.len());

    glen == elen && gb[..glen] == rest[..elen]
}

/// Mark `gname` as a candidate for the extra Unicode mappings when it
/// matches one of the extra glyph names (`ps_check_extra_glyph_name`).
fn ps_check_extra_glyph_name(
    gname: &str,
    glyph: u32,
    extra_glyphs: &mut [u32; EXTRA_GLYPH_LIST_SIZE],
    states: &mut [u8; EXTRA_GLYPH_LIST_SIZE],
) {
    for n in 0..EXTRA_GLYPH_LIST_SIZE {
        if extra_glyph_name_eq(n, gname) {
            if states[n] == 0 {
                // mark this extra glyph as a candidate for the cmap
                states[n] = 1;
                extra_glyphs[n] = glyph;
            }
            return;
        }
    }
}

/// Disable an extra mapping that the font already provides itself
/// (`ps_check_extra_glyph_unicode`).
fn ps_check_extra_glyph_unicode(uni_char: u32, states: &mut [u8; EXTRA_GLYPH_LIST_SIZE]) {
    for (n, state) in states.iter_mut().enumerate() {
        if uni_char == FT_EXTRA_GLYPH_UNICODES[n] {
            *state = 2;
            return;
        }
    }
}

/// One entry of a Unicode map (`PS_UniMap`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct PsUniMap {
    /// Unicode value; [`VARIANT_BIT`] set marks a glyph variant.
    pub unicode: u32,
    /// Index of the glyph in the font.
    pub glyph_index: u32,
}

/// A Unicode map built from the glyph names of a font (`PS_UnicodesRec`).
///
/// The embedded `FT_CMapRec` of the C structure is not ported (see the
/// crate documentation); `num_maps` and `maps` carry the payload used by
/// the character map services.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct PsUnicodes {
    /// Number of valid entries in `maps`.
    num_maps: u32,
    /// Map entries sorted by [`base_glyph`] and then by `unicode`.
    maps: Vec<PsUniMap>,
}

impl PsUnicodes {
    /// Number of Unicode mappings in the table.
    #[inline]
    pub fn num_maps(&self) -> u32 {
        self.num_maps
    }

    /// The sorted map entries.
    #[inline]
    pub fn maps(&self) -> &[PsUniMap] {
        &self.maps
    }
}

/// Sort key order used for the Unicode map (`compare_uni_maps`): base
/// glyphs are sorted before their variants, which share the base value.
fn compare_uni_maps(map1: &PsUniMap, map2: &PsUniMap) -> core::cmp::Ordering {
    let unicode1 = base_glyph(map1.unicode);
    let unicode2 = base_glyph(map2.unicode);
    unicode1
        .cmp(&unicode2)
        .then_with(|| map1.unicode.cmp(&map2.unicode))
}

/// Build a table that maps Unicode values to glyph indices
/// (`ps_unicodes_init`).
///
/// `get_glyph_name` plays the role of the C `PS_GetGlyphNameFunc` callback;
/// it receives a glyph index and returns the glyph name, or `None` when the
/// glyph has no name.  The returned [`PsUnicodes`] owns its entries, so the
/// callback's results do not need to outlive the call (which is why the C
/// `PS_FreeGlyphNameFunc` hook is not needed here).
///
/// Fails with [`TtError::OUT_OF_MEMORY`] when the map cannot be allocated
/// and with [`TtError::NO_UNICODE_GLYPH_NAME`] when no glyph resolves to a
/// Unicode value.
pub fn ps_unicodes_init<'a>(
    num_glyphs: u32,
    get_glyph_name: &dyn Fn(u32) -> Option<&'a str>,
) -> TtResult<PsUnicodes> {
    let mut extra_glyph_list_states = [0_u8; EXTRA_GLYPH_LIST_SIZE];
    let mut extra_glyphs = [0_u32; EXTRA_GLYPH_LIST_SIZE];

    let mut maps = Vec::new();
    maps.try_reserve(num_glyphs as usize + EXTRA_GLYPH_LIST_SIZE)
        .map_err(|_| TtError::OUT_OF_MEMORY)?;

    for n in 0..num_glyphs {
        if let Some(gname) = get_glyph_name(n) {
            ps_check_extra_glyph_name(gname, n, &mut extra_glyphs, &mut extra_glyph_list_states);
            let uni_char = ps_unicode_value(gname);

            if base_glyph(uni_char) != 0 {
                ps_check_extra_glyph_unicode(uni_char, &mut extra_glyph_list_states);
                maps.push(PsUniMap {
                    unicode: uni_char,
                    glyph_index: n,
                });
            }
        }
    }

    for (n, state) in extra_glyph_list_states.iter().enumerate() {
        if *state == 1 {
            // the glyph has an additional representation that the font
            // does not provide itself
            maps.push(PsUniMap {
                unicode: FT_EXTRA_GLYPH_UNICODES[n],
                glyph_index: extra_glyphs[n],
            });
        }
    }

    let count = maps.len();
    if count == 0 {
        log_error!("no Unicode glyph name found among {num_glyphs} glyphs");
        return Err(TtError::NO_UNICODE_GLYPH_NAME);
    }
    if (count as u64) < u64::from(num_glyphs) / 2 {
        maps.shrink_to(count);
    }
    // Sort in increasing order of unicode values, taking care of glyph variants.
    maps.sort_unstable_by(compare_uni_maps);

    Ok(PsUnicodes {
        num_maps: count as u32,
        maps,
    })
}

/// Return the glyph index for a Unicode value
/// (`ps_unicodes_char_index`).
///
/// Performs a binary search over the table.  When both a base glyph and a
/// variant exist for `unicode`, the base glyph wins, exactly as in the C
/// implementation.  Returns `0` when nothing matches.
pub fn ps_unicodes_char_index(table: &PsUnicodes, unicode: u32) -> u32 {
    let maps = table.maps();
    if maps.is_empty() {
        return 0;
    }

    // `min`/`max` are inclusive bounds; `i64` keeps the C pointer
    // arithmetic (where `mid - 1` may move below the array start) safe.
    let mut min = 0_i64;
    let mut max = maps.len() as i64 - 1;
    let mut result = None;

    while min <= max {
        let mid = min + (max - min) / 2;
        let map = &maps[mid as usize];

        if map.unicode == unicode {
            result = Some(map);
            break;
        }

        let base = base_glyph(map.unicode);
        if base == unicode {
            // remember the match but continue searching for a base glyph
            result = Some(map);
        }

        if min == max {
            break;
        }

        if base < unicode {
            min = mid + 1;
        } else {
            max = mid - 1;
        }
    }

    result.map_or(0, |map| map.glyph_index)
}

/// Return the glyph index for the first Unicode value greater than
/// `*unicode` and update `*unicode` to that value
/// (`ps_unicodes_char_next`).
///
/// Returns `0` and resets `*unicode` to `0` when the table is exhausted.
pub fn ps_unicodes_char_next(table: &PsUnicodes, unicode: &mut u32) -> u32 {
    let mut result = 0_u32;
    // The C code computes `*pchar_code + 1` in `FT_ULong`, so the maximum
    // code point is exhausted instead of wrapping back to `0`.
    if *unicode == u32::MAX {
        *unicode = 0;
        return 0;
    }
    let mut char_code = unicode.wrapping_add(1);

    let maps = table.maps();
    let mut min = 0_usize;
    let mut max = maps.len();

    while min < max {
        let mid = min + (max - min) / 2;
        let map = &maps[mid];

        if map.unicode == char_code {
            *unicode = char_code;
            return map.glyph_index;
        }

        let base = base_glyph(map.unicode);
        if base == char_code {
            result = map.glyph_index;
        }

        if base < char_code {
            min = mid + 1;
        } else {
            max = mid;
        }
    }

    if result != 0 {
        // we found a variant glyph
        *unicode = char_code;
        return result;
    }

    // we didn't find it; check whether we have a map just above it
    char_code = 0;
    if min < maps.len() {
        let map = &maps[min];
        result = map.glyph_index;
        char_code = base_glyph(map.unicode);
    }

    *unicode = char_code;
    result
}

/// Return the Macintosh glyph name for `name_index` as bytes
/// (`FT_Mac_Name`).
///
/// Wraps [`ps_get_macintosh_name`] but reports an out-of-range index as
/// `None` instead of clamping to index `0`, so unknown indices yield no
/// name at all.
#[inline]
pub fn macintosh_name(name_index: u32) -> Option<&'static [u8]> {
    let index = usize::try_from(name_index).ok()?;
    let offset = usize::try_from(*FT_MAC_NAMES.get(index)?).ok()?;
    Some(standard_glyph_name(offset).as_bytes())
}

/// Return the Adobe Standard Strings entry for `sid` as bytes
/// (`FT_Adobe_Std_Strings`).
///
/// Returns `None` when `sid` is out of range, matching the C function
/// returning `NULL`.
#[inline]
pub fn adobe_std_strings(sid: u32) -> Option<&'static [u8]> {
    let index = usize::try_from(sid).ok()?;
    let offset = usize::try_from(*FT_SID_NAMES.get(index)?).ok()?;
    Some(standard_glyph_name(offset).as_bytes())
}

/// Return the Unicode value of a glyph name, if the name has one
/// (`PS_Unicode_ValueFunc`).
///
/// Wraps [`ps_unicode_value`]: names the C implementation cannot resolve
/// return `0`, which is reported as `None`.  The [`VARIANT_BIT`] of glyph
/// variants such as `A.swash` is preserved.
#[inline]
pub fn unicode_value(glyph_name: &str) -> Option<u32> {
    let value = ps_unicode_value(glyph_name);
    if value == 0 { None } else { Some(value) }
}

/// The Adobe Standard Encoding (`T1_StandardEncoding`): character code to
/// Standard Strings index.
#[inline]
pub fn standard_encoding_table() -> &'static [u16; 256] {
    &T1_STANDARD_ENCODING
}

/// The Adobe Expert Encoding (`T1_ExpertEncoding`): character code to
/// Standard Strings index.
#[inline]
pub fn expert_encoding_table() -> &'static [u16; 256] {
    &T1_EXPERT_ENCODING
}

/// A Unicode character map built from glyph Unicode values
/// (`PS_UnicodesRec`).
///
/// Wraps the [`PsUnicodes`] table built by [`unicodes_init`] and exposes
/// the mandated lookup and iteration API.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct UnicodeMap {
    /// Entries sorted by [`base_glyph`] and then by `unicode`.
    table: PsUnicodes,
}

impl UnicodeMap {
    /// Wrap a table produced by [`ps_unicodes_init`].
    #[inline]
    pub fn from_ps_unicodes(table: PsUnicodes) -> Self {
        Self { table }
    }

    /// The underlying [`PsUnicodes`] table.
    #[inline]
    pub fn ps_unicodes(&self) -> &PsUnicodes {
        &self.table
    }

    /// Return the glyph index mapped to `char_code`, if any.
    ///
    /// A base glyph always wins over a variant that shares its Unicode
    /// value; `None` is returned for unmapped code points.
    #[inline]
    pub fn char_index(&self, char_code: u32) -> Option<u32> {
        let glyph_index = ps_unicodes_char_index(&self.table, char_code);
        if glyph_index == 0 { None } else { Some(glyph_index) }
    }

    /// Return the first mapped code point greater than `char_code`
    /// together with its glyph index (`FT_Get_Next_Char` semantics).
    ///
    /// Returns `None` when the map holds no code point above `char_code`.
    pub fn char_next(&self, char_code: u32) -> Option<(u32, u32)> {
        let mut next = char_code;
        let glyph_index = ps_unicodes_char_next(&self.table, &mut next);
        if glyph_index == 0 {
            None
        } else {
            Some((next, glyph_index))
        }
    }
}

/// Build a [`UnicodeMap`] from a glyph index to Unicode value lookup
/// (`PS_Unicodes_InitFunc`).
///
/// `lookup` receives a glyph index and returns the Unicode value of that
/// glyph — with [`VARIANT_BIT`] set for glyph variants — or `None` when the
/// glyph has no Unicode value.  The full 16-bit glyph index range
/// `0..=u32::from(u16::MAX)` is probed in order.
///
/// Because the lookup yields values rather than glyph names, the extra
/// glyph list of the C implementation (which adds a second Unicode value
/// for names such as `Delta`) cannot be applied and is skipped.
///
/// Returns an empty map when no glyph resolves to a Unicode value, and a
/// truncated map if the allocator runs out of memory.
pub fn unicodes_init(lookup: &mut dyn FnMut(u32) -> Option<u32>) -> UnicodeMap {
    let mut maps = Vec::new();

    for glyph_index in 0..=u32::from(u16::MAX) {
        if maps.len() == maps.capacity() && maps.try_reserve(64).is_err() {
            break;
        }
        if let Some(unicode) = lookup(glyph_index)
            && base_glyph(unicode) != 0
        {
            maps.push(PsUniMap { unicode, glyph_index });
        }
    }

    maps.sort_unstable_by(compare_uni_maps);
    UnicodeMap {
        table: PsUnicodes {
            num_maps: maps.len() as u32,
            maps,
        },
    }
}

/// Signature of the Unicode map builder (`PS_Unicodes_InitFunc`).
///
/// `get_name` maps a glyph index to its PostScript name, if any.
pub type PsUnicodesInitFunc = for<'a> fn(u32, &dyn Fn(u32) -> Option<&'a str>) -> TtResult<PsUnicodes>;

/// The `postscript-cmaps` service record (`FT_Service_PsCMapsRec`).
///
/// The fields mirror the C function pointers; they are plain `fn` pointers
/// so the record can be stored in a `static`.
pub struct PsCMapsService {
    /// Adobe glyph name to Unicode value (`PS_Unicode_ValueFunc`).
    pub unicode_value: fn(&str) -> u32,
    /// Build a Unicode map from glyph names (`PS_Unicodes_InitFunc`).
    pub unicodes_init: PsUnicodesInitFunc,
    /// Unicode value to glyph index lookup (`PS_Unicodes_CharIndexFunc`).
    pub unicodes_char_index: fn(&PsUnicodes, u32) -> u32,
    /// Iteration over the Unicode map (`PS_Unicodes_CharNextFunc`).
    pub unicodes_char_next: fn(&PsUnicodes, &mut u32) -> u32,
    /// Macintosh name id to glyph name (`PS_Macintosh_NameFunc`).
    pub macintosh_name: fn(u32) -> &'static str,
    /// Adobe standard string id to glyph name (`PS_Adobe_Std_StringsFunc`).
    pub adobe_std_strings: fn(u32) -> Option<&'static str>,
    /// Adobe Standard Encoding: indices into the Standard Strings table.
    pub adobe_std_encoding: &'static [u16; 256],
    /// Adobe Expert Encoding: indices into the Standard Strings table.
    pub adobe_expert_encoding: &'static [u16; 256],
}

/// The `pscmaps_interface` service instance (`FT_DEFINE_SERVICE_PSCMAPSREC`).
pub static PSCMAPS_INTERFACE: PsCMapsService = PsCMapsService {
    unicode_value: ps_unicode_value,
    unicodes_init: ps_unicodes_init,
    unicodes_char_index: ps_unicodes_char_index,
    unicodes_char_next: ps_unicodes_char_next,
    macintosh_name: ps_get_macintosh_name,
    adobe_std_strings: ps_get_standard_strings,
    adobe_std_encoding: &T1_STANDARD_ENCODING,
    adobe_expert_encoding: &T1_EXPERT_ENCODING,
};

/// One entry of a module service list (`FT_ServiceDescRec`).
///
/// The C record stores a type-erased `const void*`; here the list of the
/// `psnames` module only carries PostScript charmap services, so the
/// pointer stays typed.
pub struct ServiceDesc {
    /// Service identifier, e.g. [`FT_SERVICE_ID_POSTSCRIPT_CMAPS`].
    pub id: &'static str,
    /// Interface record exported for `id`.
    pub interface: &'static PsCMapsService,
}

/// The service list of the `psnames` module (`pscmaps_services`).
pub static PSNAMES_SERVICES: [ServiceDesc; 1] = [ServiceDesc {
    id: FT_SERVICE_ID_POSTSCRIPT_CMAPS,
    interface: &PSCMAPS_INTERFACE,
}];

/// Look up a service by its identifier (`psnames_get_service`).
///
/// Equivalent to `ft_service_list_lookup(PSNAMES_SERVICES_GET, service_id)`.
pub fn psnames_get_service(service_id: &str) -> Option<&'static PsCMapsService> {
    PSNAMES_SERVICES
        .iter()
        .find(|desc| desc.id == service_id)
        .map(|desc| desc.interface)
}

/// The `psnames` module class (`psnames_module_class` in `psmodule.c`).
///
/// The C entry also stores `sizeof(FT_ModuleRec)` and the `NULL`
/// constructor/destructor; there is no module object model in this crate
/// yet, so only the data that has a Rust counterpart is kept.
pub struct PsNamesModuleClass {
    /// Module flags: `0`, neither a font driver nor a renderer.
    pub flags: u32,
    /// Module name: `"psnames"`.
    pub name: &'static str,
    /// Module version: `0x10000`.
    pub version: u32,
    /// FreeType version required by the module: `0x20000`.
    pub requires: u32,
    /// Module specific interface: the `postscript-cmaps` service record.
    pub interface: &'static PsCMapsService,
    /// Service requester of the module.
    pub requester: fn(&str) -> Option<&'static PsCMapsService>,
}

/// The `psnames` module class instance (`FT_DEFINE_MODULE`).
pub static PSNAMES_MODULE_CLASS: PsNamesModuleClass = PsNamesModuleClass {
    flags: 0,
    name: "psnames",
    version: 0x10000,
    requires: 0x20000,
    interface: &PSCMAPS_INTERFACE,
    requester: psnames_get_service,
};

