#[cfg(test)]
mod tests {
    use super::*;

    /// Glyph names of a small synthetic font used by the charmap tests.
    const FONT_NAMES: [&str; 7] = [
        ".notdef", // 0: resolves to Unicode 0, dropped
        "A",       // 1: 0x0041
        "B",       // 2: 0x0042
        "A.swash", // 3: 0x0041 | VARIANT_BIT
        "uni0043", // 4: 0x0043
        "space",   // 5: 0x0020 + extra 0x00A0
        "hyphen",  // 6: 0x002D + extra 0x00AD
    ];

    fn font_glyph_name(index: u32) -> Option<&'static str> {
        FONT_NAMES.get(index as usize).copied()
    }

    #[test]
    fn table_sizes_and_offsets() {
        assert_eq!(FT_STANDARD_GLYPH_NAMES.len(), 3696);
        assert_eq!(FT_ADOBE_GLYPH_LIST.len(), 55997);
        assert_eq!(FT_MAC_NAMES.len(), FT_NUM_MAC_NAMES);
        assert_eq!(FT_SID_NAMES.len(), FT_NUM_SID_NAMES);

        // every index points at a NUL-terminated name inside the table
        for &offset in FT_MAC_NAMES.iter().chain(FT_SID_NAMES.iter()) {
            assert!(offset >= 0);
            let offset = offset as usize;
            assert!(offset < FT_STANDARD_GLYPH_NAMES.len());
            assert!(FT_STANDARD_GLYPH_NAMES[offset..].contains(&0));
        }

        for &offset in FT_EXTRA_GLYPH_NAME_OFFSETS.iter() {
            assert!(FT_EXTRA_GLYPH_NAMES[offset..].contains(&0));
        }
    }

    #[test]
    fn adobe_glyph_list_lookup() {
        assert_eq!(ft_get_adobe_glyph_index(b""), 0);
        assert_eq!(ft_get_adobe_glyph_index(b"A"), 0x0041);
        assert_eq!(ft_get_adobe_glyph_index(b"a"), 0x0061);
        assert_eq!(ft_get_adobe_glyph_index(b"Aacute"), 0x00C1);
        assert_eq!(ft_get_adobe_glyph_index(b"space"), 0x0020);
        assert_eq!(ft_get_adobe_glyph_index(b"Alpha"), 0x0391);
        assert_eq!(ft_get_adobe_glyph_index(b"bullet"), 0x2022);
        assert_eq!(ft_get_adobe_glyph_index(b"fraction"), 0x2044);

        // names the list does not know
        assert_eq!(ft_get_adobe_glyph_index(b"foobar"), 0);
        assert_eq!(ft_get_adobe_glyph_index(b"uniXYZZ"), 0);
        assert_eq!(ft_get_adobe_glyph_index(b"A.swash"), 0);
        // `.notdef` has no Unicode value
        assert_eq!(ft_get_adobe_glyph_index(b".notdef"), 0);
        // only the leading part of the name may be searched
        assert_eq!(ft_get_adobe_glyph_index(&b"Aacute"[..2]), 0);
    }

    #[test]
    fn unicode_value_from_hardcoded_digits() {
        assert_eq!(ps_unicode_value("uni0041"), 0x0041);
        assert_eq!(ps_unicode_value("uni00E9"), 0x00E9);
        // a variant of a hard-coded value
        assert_eq!(ps_unicode_value("uni0041.swash"), 0x0041 | VARIANT_BIT);
        // exactly four digits are required
        assert_eq!(ps_unicode_value("uni004"), 0);
        assert_eq!(ps_unicode_value("uni00410"), 0);
        // only uppercase hexadecimal digits are accepted
        assert_eq!(ps_unicode_value("uni004a"), 0);

        assert_eq!(ps_unicode_value("u0041"), 0x0041);
        assert_eq!(ps_unicode_value("u000041"), 0x0041);
        assert_eq!(ps_unicode_value("u00E9"), 0x00E9);
        assert_eq!(ps_unicode_value("u0041.final"), 0x0041 | VARIANT_BIT);
        // fewer than four digits is not a hard-coded value
        assert_eq!(ps_unicode_value("u041"), 0);
        // `uni` names fall through to this rule when they are malformed
        assert_eq!(ps_unicode_value("un"), 0);
    }

    #[test]
    fn unicode_value_from_glyph_list_and_variants() {
        assert_eq!(ps_unicode_value("A"), 0x0041);
        assert_eq!(ps_unicode_value("aacute"), 0x00E1);
        assert_eq!(ps_unicode_value("bullet"), 0x2022);

        // variants are flagged but keep the base glyph value
        assert_eq!(ps_unicode_value("A.swash"), 0x0041 | VARIANT_BIT);
        assert_eq!(ps_unicode_value("e.final"), 0x0065 | VARIANT_BIT);
        assert_eq!(base_glyph(ps_unicode_value("A.swash")), 0x0041);

        // an initial dot is part of the name, not a variant marker
        assert_eq!(ps_unicode_value(".notdef"), 0);
        assert_eq!(ps_unicode_value(".null"), 0);

        // unknown names resolve to zero
        assert_eq!(ps_unicode_value("foobar"), 0);
        assert_eq!(ps_unicode_value(""), 0);
    }

    #[test]
    fn macintosh_and_standard_strings() {
        assert_eq!(ps_get_macintosh_name(0), ".notdef");
        assert_eq!(ps_get_macintosh_name(1), ".null");
        assert_eq!(ps_get_macintosh_name(257), "dcroat");
        // out-of-range indices are clamped to index 0
        assert_eq!(ps_get_macintosh_name(FT_NUM_MAC_NAMES as u32), ".notdef");
        assert_eq!(ps_get_macintosh_name(u32::MAX), ".notdef");

        assert_eq!(ps_get_standard_strings(0), Some(".notdef"));
        assert_eq!(ps_get_standard_strings(1), Some("space"));
        assert_eq!(ps_get_standard_strings(34), Some("A"));
        assert_eq!(ps_get_standard_strings(390), Some("Semibold"));
        assert_eq!(ps_get_standard_strings(FT_NUM_SID_NAMES as u32), None);
        assert_eq!(ps_get_standard_strings(u32::MAX), None);
    }

    #[test]
    fn encodings_index_the_standard_strings() {
        // Standard Encoding: character code -> SID -> glyph name
        assert_eq!(T1_STANDARD_ENCODING[32], 1);
        assert_eq!(T1_STANDARD_ENCODING[65], 34);
        assert_eq!(T1_STANDARD_ENCODING[97], 66);
        assert_eq!(
            ps_get_standard_strings(u32::from(T1_STANDARD_ENCODING[65])),
            Some("A")
        );
        assert_eq!(
            ps_get_standard_strings(u32::from(T1_STANDARD_ENCODING[32])),
            Some("space")
        );
        assert_eq!(T1_STANDARD_ENCODING[0], 0);

        // Expert Encoding: 'A' maps to `asuperior`
        assert_eq!(T1_EXPERT_ENCODING[65], 253);
        assert_eq!(
            ps_get_standard_strings(u32::from(T1_EXPERT_ENCODING[65])),
            Some("asuperior")
        );
        assert_eq!(T1_EXPERT_ENCODING[32], 1);
    }

    #[test]
    fn unicodes_table_is_sorted_with_variants_last() {
        let table = ps_unicodes_init(FONT_NAMES.len() as u32, &font_glyph_name).unwrap();

        // ".notdef" has no Unicode value; the extra mappings for `space`
        // (U+00A0) and `hyphen` (U+00AD) are appended
        assert_eq!(table.num_maps(), 8);

        let unis: Vec<u32> = table.maps().iter().map(|m| m.unicode).collect();
        assert_eq!(
            unis,
            vec![
                0x0020,
                0x002D,
                0x0041,
                0x0041 | VARIANT_BIT,
                0x0042,
                0x0043,
                0x00A0,
                0x00AD,
            ]
        );

        // base glyphs sort before their variants
        let a = table.maps()[2];
        let a_swash = table.maps()[3];
        assert_eq!((a.unicode, a.glyph_index), (0x0041, 1));
        assert_eq!((a_swash.unicode, a_swash.glyph_index), (0x0041 | VARIANT_BIT, 3));

        // the extra mappings reuse the glyph that carried the name
        assert_eq!(table.maps()[6].glyph_index, 5); // space -> U+00A0
        assert_eq!(table.maps()[7].glyph_index, 6); // hyphen -> U+00AD
    }

    #[test]
    fn unicodes_char_index_prefers_base_glyphs() {
        let table = ps_unicodes_init(FONT_NAMES.len() as u32, &font_glyph_name).unwrap();

        assert_eq!(ps_unicodes_char_index(&table, 0x0020), 5);
        assert_eq!(ps_unicodes_char_index(&table, 0x002D), 6);
        assert_eq!(ps_unicodes_char_index(&table, 0x0041), 1);
        assert_eq!(ps_unicodes_char_index(&table, 0x0042), 2);
        assert_eq!(ps_unicodes_char_index(&table, 0x0043), 4);
        // variant only: the base value of the variant is remembered
        assert_eq!(ps_unicodes_char_index(&table, 0x00A0), 5);
        assert_eq!(ps_unicodes_char_index(&table, 0x00AD), 6);
        // absent code points
        assert_eq!(ps_unicodes_char_index(&table, 0), 0);
        assert_eq!(ps_unicodes_char_index(&table, 0x0044), 0);
        assert_eq!(ps_unicodes_char_index(&table, 0xFFFF), 0);

        // iterating the table finds every mapped code point
        let mut count = 0_u32;
        for map in table.maps() {
            let found = ps_unicodes_char_index(&table, base_glyph(map.unicode));
            assert_ne!(found, 0);
            count += 1;
        }
        assert_eq!(count, 8);
    }

    #[test]
    fn unicodes_char_next_walks_increasing_code_points() {
        let table = ps_unicodes_init(FONT_NAMES.len() as u32, &font_glyph_name).unwrap();

        let mut unicode = 0_u32;
        let mut seen = Vec::new();
        loop {
            let glyph = ps_unicodes_char_next(&table, &mut unicode);
            if glyph == 0 {
                break;
            }
            seen.push((unicode, glyph));
        }

        assert_eq!(
            seen,
            vec![
                (0x0020, 5),
                (0x002D, 6),
                (0x0041, 1),
                (0x0042, 2),
                (0x0043, 4),
                (0x00A0, 5),
                (0x00AD, 6),
            ]
        );
        // the walk stops and the cursor wraps back to 0
        assert_eq!(unicode, 0);
        // as in the C function, calling again from `unicode == 0`
        // restarts the iteration at the first entry
        assert_eq!(ps_unicodes_char_next(&table, &mut unicode), 5);
        assert_eq!(unicode, 0x0020);
    }

    #[test]
    fn unicodes_char_next_skips_missing_code_points() {
        // `.notdef` has no Unicode value and is dropped, so `A` and `Z`
        // keep the glyph indices 1 and 2
        let names = [".notdef", "A", "Z"];
        let table = ps_unicodes_init(names.len() as u32, &|i| names.get(i as usize).copied()).unwrap();
        assert_eq!(table.num_maps(), 2);

        let mut unicode = 0_u32;
        assert_eq!(ps_unicodes_char_next(&table, &mut unicode), 1);
        assert_eq!(unicode, 0x0041);
        assert_eq!(ps_unicodes_char_next(&table, &mut unicode), 2);
        assert_eq!(unicode, 0x005A);
        assert_eq!(ps_unicodes_char_next(&table, &mut unicode), 0);
        assert_eq!(unicode, 0);
    }

    #[test]
    fn unicodes_init_without_unicode_names_fails() {
        let names = [".notdef", ".null", "foobar"];
        let error = ps_unicodes_init(names.len() as u32, &|i| names.get(i as usize).copied()).unwrap_err();
        assert_eq!(error, TtError::NO_UNICODE_GLYPH_NAME);

        let error = ps_unicodes_init(4, &|_| None).unwrap_err();
        assert_eq!(error, TtError::NO_UNICODE_GLYPH_NAME);
    }

    #[test]
    fn extra_glyphs_are_only_added_when_missing() {
        // `Delta` resolves to U+2206 in this Adobe Glyph List, so the
        // WGL 4 mapping to U+0394 has to be added
        let names = ["Delta"];
        let table = ps_unicodes_init(1, &|i| names.get(i as usize).copied()).unwrap();
        assert_eq!(table.num_maps(), 2);
        // the table is sorted, so U+0394 comes first
        assert_eq!(table.maps()[0].unicode, 0x0394);
        assert_eq!(table.maps()[0].glyph_index, 0);
        assert_eq!(table.maps()[1].unicode, 0x2206);
        assert_eq!(table.maps()[1].glyph_index, 0);

        // when a glyph already provides U+0394 the extra entry is dropped
        let names = ["Delta", "Deltagreek"];
        let table = ps_unicodes_init(names.len() as u32, &|i| names.get(i as usize).copied()).unwrap();
        assert_eq!(table.num_maps(), 2);
        assert_eq!(table.maps()[0].unicode, 0x0394);
        assert_eq!(table.maps()[0].glyph_index, 1);
        assert_eq!(table.maps()[1].unicode, 0x2206);
        assert_eq!(table.maps()[1].glyph_index, 0);

        // Romanian `Tcommaaccent`: AGL gives U+0162, the extra mapping
        // adds U+021A for the same glyph
        let names = ["Tcommaaccent"];
        let table = ps_unicodes_init(1, &|i| names.get(i as usize).copied()).unwrap();
        assert_eq!(table.num_maps(), 2);
        assert_eq!(table.maps()[0].unicode, 0x0162);
        assert_eq!(table.maps()[1].unicode, 0x021A);
        assert_eq!(table.maps()[1].glyph_index, 0);
    }

    #[test]
    fn unicodes_init_handles_unnamed_glyphs() {
        // glyphs without names are skipped like the C callback returning NULL
        let names = ["A", "B"];
        let table = ps_unicodes_init(5, &|i| {
            if i < 2 {
                names.get(i as usize).copied()
            } else {
                None
            }
        })
        .unwrap();
        assert_eq!(table.num_maps(), 2);
        assert_eq!(ps_unicodes_char_index(&table, 0x0041), 0);
        assert_eq!(ps_unicodes_char_index(&table, 0x0042), 1);
    }

    #[test]
    fn service_and_module_lookup() {
        let service = psnames_get_service(FT_SERVICE_ID_POSTSCRIPT_CMAPS);
        assert!(service.is_some());
        let service = service.unwrap_or(&PSCMAPS_INTERFACE);

        assert!(core::ptr::fn_addr_eq(
            service.unicode_value,
            ps_unicode_value as fn(&str) -> u32
        ));
        assert!(core::ptr::fn_addr_eq(
            service.macintosh_name,
            ps_get_macintosh_name as fn(u32) -> &'static str
        ));
        assert!(core::ptr::fn_addr_eq(
            service.unicodes_char_index,
            ps_unicodes_char_index as fn(&PsUnicodes, u32) -> u32
        ));
        assert_eq!(service.adobe_std_encoding, &T1_STANDARD_ENCODING);
        assert_eq!(service.adobe_expert_encoding, &T1_EXPERT_ENCODING);
        assert_eq!((service.unicode_value)("uni0041"), 0x0041);
        assert_eq!((service.macintosh_name)(1), ".null");
        assert_eq!((service.adobe_std_strings)(34), Some("A"));

        assert!(psnames_get_service("postscript-font-info").is_none());
        assert!(psnames_get_service("").is_none());

        // the module class points at the same interface
        assert!(core::ptr::fn_addr_eq(
            PSNAMES_MODULE_CLASS.requester,
            psnames_get_service as fn(&str) -> Option<&'static PsCMapsService>
        ));
        assert_eq!(PSNAMES_MODULE_CLASS.name, "psnames");
        assert_eq!(PSNAMES_MODULE_CLASS.version, 0x10000);
        assert_eq!(PSNAMES_MODULE_CLASS.requires, 0x20000);
        assert_eq!(PSNAMES_MODULE_CLASS.flags, 0);
        assert!(core::ptr::eq(PSNAMES_MODULE_CLASS.interface, &PSCMAPS_INTERFACE));
        assert_eq!(PSNAMES_SERVICES.len(), 1);
        assert_eq!(PSNAMES_SERVICES[0].id, FT_SERVICE_ID_POSTSCRIPT_CMAPS);
    }

    #[test]
    fn unicodes_init_through_the_service() {
        let init = (PSCMAPS_INTERFACE.unicodes_init)(FONT_NAMES.len() as u32, &font_glyph_name)
            .unwrap_or_else(|_| PsUnicodes::default());
        assert_eq!(init.num_maps(), 8);
        assert_eq!((PSCMAPS_INTERFACE.unicodes_char_index)(&init, 0x0041), 1);
        let mut unicode = 0_u32;
        assert_eq!((PSCMAPS_INTERFACE.unicodes_char_next)(&init, &mut unicode), 5);
        assert_eq!(unicode, 0x0020);
    }

    #[test]
    fn mandated_api_macintosh_name() {
        assert_eq!(macintosh_name(0), Some(&b".notdef"[..]));
        assert_eq!(macintosh_name(1), Some(&b".null"[..]));
        assert_eq!(macintosh_name(257), Some(&b"dcroat"[..]));
        // unknown indices report no name instead of clamping to 0
        assert_eq!(macintosh_name(FT_NUM_MAC_NAMES as u32), None);
        assert_eq!(macintosh_name(u32::MAX), None);
    }

    #[test]
    fn mandated_api_adobe_std_strings() {
        assert_eq!(adobe_std_strings(0), Some(&b".notdef"[..]));
        assert_eq!(adobe_std_strings(1), Some(&b"space"[..]));
        assert_eq!(adobe_std_strings(34), Some(&b"A"[..]));
        assert_eq!(adobe_std_strings(390), Some(&b"Semibold"[..]));
        assert_eq!(adobe_std_strings(FT_NUM_SID_NAMES as u32), None);
        assert_eq!(adobe_std_strings(u32::MAX), None);
    }

    #[test]
    fn mandated_api_unicode_value() {
        assert_eq!(unicode_value("uni0041"), Some(0x0041));
        assert_eq!(unicode_value("A"), Some(0x0041));
        // variants keep the variant bit
        assert_eq!(unicode_value("A.swash"), Some(0x0041 | VARIANT_BIT));
        // unresolvable names report no value
        assert_eq!(unicode_value("uni004"), None);
        assert_eq!(unicode_value("foobar"), None);
        assert_eq!(unicode_value(".notdef"), None);
        assert_eq!(unicode_value(""), None);
    }

    #[test]
    fn mandated_api_encoding_tables() {
        let standard = standard_encoding_table();
        let expert = expert_encoding_table();
        assert_eq!(standard, &T1_STANDARD_ENCODING);
        assert_eq!(expert, &T1_EXPERT_ENCODING);
        assert_eq!(standard.len(), 256);
        assert_eq!(expert.len(), 256);
        // 'A' -> SID 34 -> "A" in the Standard Encoding
        assert_eq!(adobe_std_strings(u32::from(standard[65])), Some(&b"A"[..]));
        // 'A' -> SID 253 -> "asuperior" in the Expert Encoding
        assert_eq!(adobe_std_strings(u32::from(expert[65])), Some(&b"asuperior"[..]));
        assert_eq!(standard[0], 0);
    }

    #[test]
    fn mandated_api_unicode_map_lookup_and_iteration() {
        // fake glyph table: 0 = unnamed, 1 = "A", 2 = "B",
        // 3 = "A.swash" (variant), 4 = "uni0043"
        let mut lookup = |glyph: u32| match glyph {
            1 => Some(0x0041),
            2 => Some(0x0042),
            3 => Some(0x0041 | VARIANT_BIT),
            4 => Some(0x0043),
            _ => None,
        };
        let map = unicodes_init(&mut lookup);

        // the base glyph wins over the variant sharing its code point
        assert_eq!(map.char_index(0x0041), Some(1));
        assert_eq!(map.char_index(0x0042), Some(2));
        assert_eq!(map.char_index(0x0043), Some(4));
        assert_eq!(map.char_index(0x0044), None);
        assert_eq!(map.char_index(0), None);

        // iteration walks the mapped code points in increasing order
        assert_eq!(map.char_next(0x0040), Some((0x0041, 1)));
        assert_eq!(map.char_next(0x0041), Some((0x0042, 2)));
        assert_eq!(map.char_next(0x0042), Some((0x0043, 4)));
        assert_eq!(map.char_next(0x0043), None);

        let mut seen = Vec::new();
        let mut cursor = 0_u32;
        while let Some((code, glyph)) = map.char_next(cursor) {
            seen.push((code, glyph));
            cursor = code;
        }
        assert_eq!(seen, vec![(0x0041, 1), (0x0042, 2), (0x0043, 4)]);

        // the wrapped table is exposed for the low-level API
        assert_eq!(map.ps_unicodes().num_maps(), 4);
        assert_eq!(map.ps_unicodes().maps().len(), 4);
    }

    /// Build a [`UnicodeMap`] from the synthetic font name table through the
    /// mandated value-only lookup.
    fn map_from_names() -> UnicodeMap {
        let mut lookup = |glyph: u32| match FONT_NAMES.get(glyph as usize) {
            Some(name) => {
                let value = ps_unicode_value(name);
                if value == 0 { None } else { Some(value) }
            }
            None => None,
        };
        unicodes_init(&mut lookup)
    }

    #[test]
    fn mandated_api_unicode_map_from_glyph_names() {
        let map = map_from_names();

        // the extra glyph list needs glyph names and is not applied by the
        // value-only lookup, so `space`/`hyphen` add no second mapping
        assert_eq!(map.ps_unicodes().num_maps(), 6);
        assert_eq!(map.char_index(0x0020), Some(5));
        assert_eq!(map.char_index(0x002D), Some(6));
        assert_eq!(map.char_index(0x0041), Some(1)); // base beats "A.swash"
        assert_eq!(map.char_index(0x0043), Some(4));
        assert_eq!(map.char_index(0x00A0), None);

        // wrapping the low-level builder keeps the same behaviour
        let low_level = UnicodeMap::from_ps_unicodes(
            ps_unicodes_init(FONT_NAMES.len() as u32, &font_glyph_name).unwrap_or_default(),
        );
        assert_eq!(low_level.char_index(0x0041), Some(1));
    }

    #[test]
    fn mandated_api_unicode_map_empty() {
        let mut lookup = |_: u32| None;
        let map = unicodes_init(&mut lookup);
        assert_eq!(map.ps_unicodes().num_maps(), 0);
        assert_eq!(map.char_index(0x0041), None);
        assert_eq!(map.char_next(0), None);
    }

    #[test]
    fn char_next_at_max_code_point_exhausts() {
        // the C implementation computes the next code point in `FT_ULong`;
        // U+FFFF_FFFF must exhaust the table instead of wrapping to 0
        let table = ps_unicodes_init(FONT_NAMES.len() as u32, &font_glyph_name).unwrap_or_default();
        let mut unicode = u32::MAX;
        assert_eq!(ps_unicodes_char_next(&table, &mut unicode), 0);
        assert_eq!(unicode, 0);

        let map = UnicodeMap::from_ps_unicodes(table);
        assert_eq!(map.char_next(u32::MAX), None);
    }
}
